// Paths and sizes generated by scripts/media.py — rerun it after changing photos/videos.
import media from "./media.json";

export type PhotoName = keyof typeof media.photos;
export type PosterName = keyof typeof media.posters;

export function photoAttributes(name: PhotoName, sizes: string) {
  const photo = media.photos[name];
  const variants = photo.variants;

  return {
    src: variants[variants.length - 1].src,
    srcSet: variants.map((variant) => `${variant.src} ${variant.width}w`).join(", "),
    sizes,
    width: photo.width,
    height: photo.height
  };
}

// For the enlarged view: the image fills at most 88% of the width or 78% of the height,
// whichever is reached first (same limits as .photo-window img in style.css).
export function enlargedAttributes(name: PhotoName) {
  const photo = media.photos[name];
  const aspectRatio = photo.width / photo.height;
  const candidates = [...photo.variants, { src: photo.src, width: photo.width }];

  return {
    src: photo.variants[photo.variants.length - 1].src,
    srcSet: candidates.map((candidate) => `${candidate.src} ${candidate.width}w`).join(", "),
    sizes: `min(88vw, calc(78vh * ${aspectRatio.toFixed(4)}))`,
    width: photo.width,
    height: photo.height,
    aspectRatio
  };
}

export function posterUrl(name: PosterName): string {
  return media.posters[name];
}
